changeSet.sql:
------------------------------------------------------------------ -- Replace outdated Windows EventLog field ------------------------------------------------------------------- UPDATE utm_visualization SET filters = REPLACE(filters, 'log.wineventlogEventDataServiceName.keyword', 'log.winlogEventDataServiceName.keyword') WHERE filters IS NOT NULL;
UPDATE utm_visualization SET aggregation = REPLACE(aggregation, 'log.wineventlogEventDataServiceName.keyword', 'log.winlogEventDataServiceName.keyword') WHERE aggregation IS NOT NULL;
